        require(ok, "funding failed");

        // First call: may succeed or revert depending on leftover balance from deployment.
        try c.sendTo(receiver, amount) {} catch {}

        // Deciding call: second call with same args must revert.
        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

    receive() external payable {}
}

